package vn.covie.notifications.model;
import com.fasterxml.jackson.databind.JsonNode; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="notifications") public class NotificationEntity {
 @Id private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Enumerated(EnumType.STRING) @Column(name="notification_type",nullable=false) private NotificationType notificationType; @Column(nullable=false) private String title; @Column(nullable=false) private String body; @Column(name="related_entity_type") private String relatedEntityType; @Column(name="related_entity_id") private UUID relatedEntityId; @JdbcTypeCode(SqlTypes.JSON) @Column(columnDefinition="jsonb") private JsonNode payload; @Column(name="source_outbox_event_id") private UUID sourceOutboxEventId; @Column(name="read_at") private Instant readAt; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="expires_at") private Instant expiresAt;
 protected NotificationEntity(){} public static NotificationEntity create(UUID id,UUID user,NotificationType type,String title,String body,String relatedType,UUID relatedId,JsonNode payload,UUID source,Instant now){NotificationEntity n=new NotificationEntity();n.id=id;n.userId=user;n.notificationType=type;n.title=title;n.body=body;n.relatedEntityType=relatedType;n.relatedEntityId=relatedId;n.payload=payload;n.sourceOutboxEventId=source;n.createdAt=now;return n;} public UUID getId(){return id;} public UUID getUserId(){return userId;} public NotificationType getNotificationType(){return notificationType;} public JsonNode getPayload(){return payload;} public Instant getReadAt(){return readAt;} public Instant getCreatedAt(){return createdAt;} public void markRead(Instant now){if(readAt==null)readAt=now;}
}
